import {lucyLocation} from './town.js?v=0.13.3';
import {ROOMS,DOORS} from './indoors.js?v=0.13.3';
import {FISH,FISH_SPOT,newCast,hookCast,stepCast} from './fishing.js?v=0.13.3';
import {availableAtHome,soupReason} from './life.js?v=0.13.3';
import {itemArt} from './item-art.js?v=0.13.3';
export function createLifeUI({getState,world,run,openModal,closeModal,button,mini,dialogue,toast,chime,showHome,showLucy,showVera,showShop,showJournal,ITEMS,hillRecipes}){
 const $=q=>document.querySelector(q);let cast=null,paused=false,lastStage='',visit=false;
 const panel=(title,body,kind='life')=>openModal(kind,'',title,body);
 const actions=html=>`<div class="action-list">${html}</div>`;
 function moveRoom(room){if(run(room?'enterRoom':'exitRoom',room?{room}:{})){closeModal();world.visitor=false;visit=false;$('#world').classList.remove('scene-enter');void $('#world').offsetWidth;$('#world').classList.add('scene-enter');}}
 function go(id){closeModal();world.go(ROOMS[getState().life.room].spots.find(p=>p.id===id));}
 function stove(){panel('炉火与晚餐',()=>{
  const s=getState(),have=k=>availableAtHome(s,k);
  return `<p>家中的箱子也算厨房储备，先使用背包里的材料。</p><div class="home-recipes"><section>${itemArt('pie')}<h3>南瓜派</h3><p>南瓜 ${have('pumpkin')}/1 · 面粉 ${have('flour')}/1 · 蜂蜜 ${have('honey')}/1</p>${actions(button('烤一份南瓜派',()=>{if(run('cookHome',{recipe:'pie'}))stove();},{primary:true,disabled:!s.flags.metLucy?'先向露西学习配方':have('pumpkin')<1||have('flour')<1||have('honey')<1?'材料不足':s.energy<4?'体力不足':'',small:'体力 4 · 20 分钟'}))}</section><section>${itemArt('fishSoup')}<h3>香草鱼汤</h3><p>普通鱼 ${have('silver')+have('carp')}/2 · 干香草 ${have('driedHerb')}/1</p><p class="small-note">使用银尾小鱼或河鲫；干香草在雾松林制作。用于晚餐或出售。</p>${actions(button('煮一份香草鱼汤',()=>{if(run('cookHome',{recipe:'fishSoup'}))stove();},{primary:true,disabled:soupReason(s),small:'体力 4 · 15 分钟'}))}</section>${s.neighborhood.lucy===3?`<section>${itemArt('pie')}<h3>苹果小酥饼</h3><p>苹果 ${have('apple')}/1 · 面粉 ${have('flour')}/1 · 蜂蜜 ${have('honey')}/1</p>${actions(button('烤苹果小酥饼',()=>{if(run('cookHome',{recipe:'applePastry'}))stove();},{primary:true,disabled:have('apple')<1||have('flour')<1||have('honey')<1?'材料不足':s.energy<4?'体力不足':'',small:'体力4 · 20分钟'}))}</section>`:''}</div>${hillRecipes?.(stove)||''}`;
 });}
 function chest(){panel('家中的储物箱',()=>{
  const s=getState();return `<p>物品按种类堆叠。家中做饭可直接使用这里的材料；户外制作使用随身背包。</p><div class="storage-list">${Object.entries(ITEMS).filter(([k])=>s.inventory[k]||s.life.chest[k]).map(([k,i])=>`<div class="storage-row">${itemArt(k)}<div><strong>${i.name}</strong><small>随身 ${s.inventory[k]} · 箱内 ${s.life.chest[k]||0}</small></div><div>${mini('存 1',()=>{if(run('storage',{item:k}))chest();},!s.inventory[k])}${mini('全存',()=>{if(run('storage',{item:k,all:true}))chest();},!s.inventory[k])}${mini('取 1',()=>{if(run('storage',{item:k,take:true}))chest();},!s.life.chest[k])}${mini('全取',()=>{if(run('storage',{item:k,take:true,all:true}))chest();},!s.life.chest[k])}</div></div>`).join('')||'<p>箱子和背包都是空的。</p>'}</div>${actions(button('把随身材料全部存好',()=>{for(const k of ['wood','stone','herb','resin','driedHerb','wheat','pumpkin','flour','honey'])if(getState().inventory[k])run('storage',{item:k,all:true});chest();}))}`;
 });}
 function dinner(){panel('河上的第一顿晚餐',()=>{
  const s=getState(),l=s.life;return `${dialogue('露西','总会多准备一只碗的人',l.dinner?'那天的汤有一点河风的味道。下回换我带面包。':l.catches?'河边总算又有人坐下来了。带两条普通鱼回家，添一把干香草，我们一起煮锅汤吧。':'河边的旧鱼竿还可以用。先去试试吧，近水的小鱼很适合熬汤。')}<p>${l.dinner?'晚餐已经完成。家中餐桌可以邀请露西来坐一会儿。':l.invited?'普通鱼 2 条 + 干香草 1 → 家中灶台煮汤 → 带到旧渡口河岸长椅。没有期限。':'先去旧渡口钓鱼，回来找我约好晚餐。'}</p>${actions(!l.invited?button('约好河边的晚餐',()=>{if(run('inviteDinner'))dinner();},{primary:true,disabled:!l.catches?'先钓到一条鱼':''}):button('记住了，慢慢准备',closeModal,{primary:true}))}`;
 },'lucy');}
 function tea(){world.seated=structuredClone(ROOMS.shop.seats);panel('在窗边坐一会儿',()=>{
  const s=getState();return `${dialogue('露西','忙完这一阵，就喝杯茶',s.life.dinner?'锅底一点都没剩。原来一顿饭也能让渡口重新有了名字。':s.expansion.flags.veraDeparted?'她的扣针还在河边。我想，留下来的东西，也会替人说话。':s.life.catches?'鱼第一次上钩的时候，你是不是也差点忘了收线？':s.flags.departed?'爷爷的磨轮还在转。我现在听见它，心里不会那么空了。':'以前爷爷一坐下，就把最热的面包推给我。现在换我给来这里的人留一份。')}<p class="small-note">窗外是小镇的声音。没有必须说完的话，也没有倒计时。</p>${actions(button('谢谢你留的位置',closeModal,{primary:true}))}`;
 },'lucy');}
 function dining(){panel('桌边还留着一个位置',()=>{
  const s=getState();return `<p>${s.life.dinner?'河边那顿晚餐之后，露西答应有空就来喝茶。':'先在旧渡口钓鱼，再去找露西商量一顿河边晚餐。'}</p>${actions(button('邀请露西来坐一会儿',()=>{closeModal();world.visitor=true;visit=true;world.go({...ROOMS.home.spots.find(p=>p.id==='dining'),id:'visitLucy'});},{primary:true,disabled:!s.life.dinner?'完成河边晚餐后开放':''})+button('翻看钓鱼笔记',fishJournal)+button('查看旅途记录',()=>showJournal('notes')))}`;
 });}
 function keepsake(){panel('留下来的小东西',()=>{const s=getState();return `<div class="keepsake-list"><p>${s.flags.festival?'✓ 丰收节的麦穗：长桌重新热闹起来。':'一只空花瓶，等着装下第一个丰收的秋天。'}</p><p>${s.life.catches?'✓ 鱼类笔记：记下河里遇见的每一个小家伙。':'这里可以放一本河岸笔记。'}</p><p>${s.expansion.flags.veraDeparted?'✓ 铜燕子扣针：回来的路上，不用跑。':'架上还有空位，留给后来发生的故事。'}</p></div>${actions(button('翻开鱼类笔记',fishJournal))}`;});}
 function mail(id){const s=getState();if(id==='sortMail'){panel('分拣桌上的回信',()=>`<p>${s.life.mailSorted?'信件按路线整整齐齐放好了。有一封写着：“不用急，饭会替你温着。”':'旧信封上写着不同的门牌。最底下那一封，只写了“给送信的人”。'}</p>${actions(button('替回信找好位置',()=>{if(run('sortMail'))mail(id);},{primary:true,disabled:!s.expansion.flags.metVera?'先去河边认识薇拉':s.life.mailSorted?'信件已经归位':''})+button('先收好这段回忆',closeModal))}`);return;}
  panel(id==='archive'?'邮路还记得她':'后来的人留下的话',()=>`<p>${id==='archive'?(s.expansion.flags.ledger?'你已经读过回程邮册：所有信件均已送达。她没有欠任何人一封信。':'路线图上，最远的门牌旁画着一碗汤。真正的回程邮册藏在雾松林的旧木箱里。'):(s.life.dinner?'露西写道：“今天河边有热汤。下次记得带面包。”':s.expansion.flags.posted?'“回来的路上，不用跑。”新留言盖住了一点旧灰尘。':'留言簿留着许多空白。等河岸重新有人来，也会有新的故事。')}</p>${actions(button('继续在屋里看看',closeModal,{primary:true}))}`);
 }
 function fishingMenu(){panel('旧渡口 · 抛下一竿',()=>{const s=getState();return `<p>坐在桥的尽头，把浮漂抛向左侧水面。鱼竿不会损坏，不需要鱼饵。</p><p class="fishing-conditions">旧渡口河流 · ${s.weather==='rain'?'雨天':'晴天'} · ${s.minute>=1080?'夜晚':'白天'} · ${s.lantern?'提灯已点亮':'提灯未点亮'}</p><p class="small-note">近水全天都是普通鱼；远水白天可遇苔背鲈，夜晚持灯可遇灯影鳗，雨夜更常见。第一竿保证银尾小鱼。</p>${!s.life.rod?actions(button('领取桶边的旧鱼竿',()=>{if(run('claimRod'))fishingMenu();},{primary:true})): `<div class="fishing-choices">${button('抛向近水',()=>start('near'),{primary:true,disabled:s.energy<3?'体力不足':'',small:'普通小鱼与河鲫 · 适合做汤'})}${button('抛向远水',()=>start('far'),{disabled:s.energy<3?'体力不足':'',small:'白天可能有鲈鱼，夜晚持灯可能有鳗鱼'})}</div><p>每次有效抛竿：体力 3、时间 10 分钟。小游戏期间钟表暂停；取消和脱钩不退回本次消耗。</p><p><strong>浮漂下沉时按空格提竿；按住收线，松开卸力。</strong>张力处在绿色区间时，鱼会靠近岸边。</p>${actions(button(s.life.assist?'辅助收线：开启':'辅助收线：关闭',()=>{if(run('fishAssist'))fishingMenu();},{small:'自动调节张力 · 鱼和奖励相同'})+button('看看鱼类笔记',fishJournal))}`}`;});}
 function fishJournal(){panel('河岸笔记',()=>{const s=getState();return `<div class="fish-journal">${Object.entries(FISH).map(([k,f])=>{const r=s.life.records[k];return `<section>${itemArt(k)}<h3>${r?f.name:'尚未记录'}</h3><p>${f.tip}</p><p>${r?`钓获 ${r.count} 条 · 最大 ${r.max} 厘米`:'在对应水域尝试抛竿'}</p>${r?`<small>初见：秋 ${r.firstDay} 日 · ${r.depth==='near'?'近水':'远水'} · ${r.night?'夜晚':'白天'} · ${r.weather==='rain'?'雨':'晴'}</small>`:''}</section>`;}).join('')}</div>${actions(button('查看晚餐食谱',()=>panel('香草鱼汤',()=>'<p>银尾小鱼或河鲫共 2 条 + 干香草 1。在家中灶台制作；体力 4，15 分钟。干香草在雾松林晾制。</p>'))+button('合上笔记',closeModal))}`;});}
 const hud=document.createElement('section');hud.id='fishing-hud';hud.hidden=true;hud.setAttribute('aria-label','垂钓操作');hud.innerHTML='<div class="fish-status" aria-live="polite"></div><div class="fish-meter-label">鱼线张力 <b id="tension-value">48</b></div><div class="tension-track"><span class="safe-zone"></span><i></i></div><div class="fish-meter-label">收线进度</div><div class="fish-progress" role="progressbar" aria-label="收线进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i></i></div><p class="fish-instruction"></p><div class="fish-buttons"><button id="reel-button">等待浮漂</button><button id="fish-cancel">收竿离开</button><button id="fish-resume" hidden>继续钓鱼</button></div>';
 $('#game').append(hud);
 function lock(value){for(const el of $('#game').children)if(!['fishing-hud','world','toasts'].includes(el.id))el.inert=value;}
 function start(depth){if(!run('startCast',{depth}))return;closeModal();cast=newCast(getState().life.pending,getState().life.assist);lastStage='';paused=false;world.fishing=cast;world.camera();world.keys.clear();world.path=[];world.pending=null;document.body.classList.add('fishing-active');hud.hidden=false;lock(true);render();$('#reel-button').focus();}
 function finish(cancel=false){if(!cast)return;const t=cast,caught=t.stage==='caught';cast=null;world.fishing=null;world.camera();world.paused=false;paused=false;hud.hidden=true;document.body.classList.remove('fishing-active');lock(false);world.keys.clear();
  const ok=run(cancel?'cancelCast':'finishCast',cancel?{}:{id:t.id,caught});
  if(!cancel&&ok)panel(caught?'河里送来一份小礼物':'它游回河里了',()=>`${caught?`<div class="catch-result">${itemArt(t.fish)}<strong>${FISH[t.fish].name}</strong><span>${t.length} 厘米 · 已放入背包</span></div><p>${getState().life.catches===1?'第一条鱼已经记进笔记。去露西的杂货屋聊聊，也许能约上一顿晚餐。':'可以出售，也可以把普通鱼留着煮汤。'}</p>`:'<p>鱼竿完好，只消耗了这一竿的体力和时间。尝试松开按钮卸力，或在抛竿前开启辅助收线。</p>'}${actions(button('再抛一竿',fishingMenu,{primary:true})+button('收好鱼竿，继续走走',closeModal))}`);
  else $('#world').focus();
 }
 function render(){if(!cast)return;const stage=cast.stage,status=paused?'暂时停一停':stage==='cast'?'鱼线划过水面':stage==='wait'?'等浮漂真正沉下去…':stage==='bite'?'咬钩了！现在提竿':cast.warning?'鱼要发力了，准备松线':'稳住鱼线，慢慢带回岸边';
  if(status!==lastStage){if(stage==='bite'&&!paused)chime?.();$('.fish-status').textContent=status;lastStage=status;}
  $('#tension-value').textContent=Math.round(cast.tension);$('.tension-track i').style.left=cast.tension+'%';$('.fish-progress i').style.width=cast.progress+'%';$('.fish-progress').setAttribute('aria-valuenow',Math.round(cast.progress));
  $('#reel-button').textContent=stage==='bite'?'提竿！':stage==='reel'?(cast.assist?'辅助收线中':cast.held?'收线中 · 松开卸力':'按住收线'):'等待浮漂';$('#reel-button').disabled=paused||!['bite','reel'].includes(stage);$('#fish-resume').hidden=!paused;$('.fish-instruction').textContent=paused?'返回后点击继续；这一竿不会自行流逝。':stage==='reel'?'绿色区间推进 · 过松暂停 · 红区持续 1.5 秒会脱钩':'空格或下方按钮 · Esc 收竿';
 }
 function down(){if(!cast||paused)return;if(cast.stage==='bite')hookCast(cast);else if(cast.stage==='reel')cast.held=true;render();}
 $('#reel-button').addEventListener('pointerdown',e=>{e.preventDefault();e.currentTarget.setPointerCapture?.(e.pointerId);down();});
 for(const name of ['pointerup','pointercancel','lostpointercapture'])$('#reel-button').addEventListener(name,()=>{if(cast)cast.held=false;});
 $('#reel-button').addEventListener('click',e=>{if(e.detail===0)down();});
 $('#fish-cancel').onclick=()=>finish(true);$('#fish-resume').onclick=()=>{paused=false;world.paused=false;render();$('#reel-button').focus();};
 const pause=()=>{if(cast){paused=true;world.paused=true;cast.held=false;render();}};window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('keyup',e=>{if(cast&&[' ','Enter'].includes(e.key))cast.held=false;});
 return {
  get active(){return !!cast;},get visiting(){return visit;},fishJournal,dinner,tea,
  releaseVisit(){visit=false;world.visitor=false;world.seated=null;},
  key(e){if(!cast)return false;if(e.key==='Tab'){const bs=[...hud.querySelectorAll('button')].filter(b=>!b.disabled&&!b.hidden),at=bs.indexOf(document.activeElement);e.preventDefault();bs[(at+(e.shiftKey?bs.length-1:1)+bs.length)%bs.length]?.focus();return true;}e.preventDefault();if(e.key==='Escape')finish(true);else if([' ','Enter'].includes(e.key)&&!e.repeat){if(document.activeElement===$('#fish-cancel'))finish(true);else if(paused){paused=false;world.paused=false;render();}else down();}return true;},
  frame(dt){if(!cast||paused)return;stepCast(cast,dt);if(['caught','escaped'].includes(cast.stage))finish();else render();},
  handle(target){if(cast)return true;const s=getState();
   if(['indoorLucy','counter','teaTable','orders'].includes(target.id)&&s.life.room==='shop'&&lucyLocation(s).scene!=='shop'){panel('露西留的便笺',()=>`<p>我去${lucyLocation(s).scene==='hall'?'会馆厨房':'广场面包摊'}了。买种子、交付和聊天都可以在那里找我。</p>${actions(button('查看村民去向',()=>showJournal('town'),{primary:true})+button('稍后再来',closeModal))}`);return true;}
   if(target.id==='visitLucy'){world.seated={keeper:{x:739,y:481},lucy:{x:958,y:481}};panel('炉火边的来访',()=>`${dialogue('露西','来喝一杯茶的朋友','原来你把这里收拾成这样了。下次我带面包来，你负责把水烧开就好。')}<p>她在桌边坐下，讲起今天杂货屋的小事。窗外的路还长，眼前的茶正温。</p>${actions(button('下次再来',()=>{visit=false;world.visitor=false;closeModal();},{primary:true}))}`,'lucy');return true;}
   if(s.life.room){const f={roomExit:()=>moveRoom(null),bed:showHome,stove,chest,dining,keepsake,indoorLucy:showLucy,counter:()=>showShop('buy'),teaTable:tea,orders:()=>go('indoorLucy'),sortMail:()=>mail('sortMail'),archive:()=>mail('archive'),guestbook:()=>mail('guestbook'),indoorVera:()=>{if(!s.expansion.flags.metVera||s.minute<1080||!s.lantern||s.expansion.flags.veraDeparted)panel('留给邮差的位置',()=>`<p>${s.expansion.flags.veraDeparted?'薇拉已经踏上回程。她留下的字迹和晾草手艺仍在这里。':!s.expansion.flags.metVera?'先到河岸认识薇拉。修复引航灯，丰收节后夜晚持灯带上花茶。':'薇拉夜晚会来这里。18:00 后点亮提灯再看看。'}</p>`);else showVera();}};f[target.id]?.();return true;}
   if(target.id==='home'){moveRoom('home');return true;}if(target.id==='lucy'&&s.flags.metLucy){moveRoom('shop');return true;}if(target.id==='postDoor'){moveRoom('post');return true;}if(target.id==='fishing'){fishingMenu();return true;}
   if(target.id==='vera'&&s.expansion.flags.metVera&&!s.expansion.flags.veraDeparted){panel('她在邮驿里等你',()=>`<p>河边留着一张便笺：“我去分拣桌那边坐坐。夜晚带着灯进来，就能找到我。”</p>${actions(button('走到邮驿门口',()=>{closeModal();world.go({...DOORS.post,id:'postDoor'});},{primary:true}))}`);return true;}
   return false;
  },
  benchExtra(){const l=getState().life;return l.invited&&!l.dinner?button('摆上河边的晚餐',()=>{if(run('serveDinner'))panel('河上的第一顿晚餐',()=>`${dialogue('露西','给送信的人留了位置',getState().expansion.flags.veraDeparted?'那枚铜燕子旁边，也放一只碗吧。她会知道我们记得。':'等她送完信，就能喝到热汤。今晚不用赶路。')}<p>餐布铺在长椅边。你们把碗放好，河岸终于又有了停下来的人。</p>${actions(button('下次还来这里吃饭',closeModal,{primary:true}))}`);},{primary:true,disabled:getState().inventory.fishSoup<1?'带一份家中煮好的香草鱼汤':''}):'';}
 };
}
